package com.quicknotes.app;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.webkit.*;import android.widget.*;import org.json.*;
public class MapsActivity extends Activity {
 WebView map;public void onCreate(Bundle b){super.onCreate(b);try{String key=getSharedPreferences("maps",0).getString("key","");if(key.isEmpty())throw new Exception("Add your Google Maps JavaScript API key in Sync Settings first.");JSONObject config=new JSONObject().put("lat",getIntent().getDoubleExtra("lat",40)).put("lng",getIntent().getDoubleExtra("lng",-74)).put("radius",getIntent().getDoubleExtra("radius",100.584)).put("address",getIntent().getStringExtra("address"));String html=new String(MainActivity.bytes(getAssets().open("maps.html"),100000),"UTF-8").replace("__CONFIG__",config.toString().replace("<","\\u003c")).replace("__KEY__",Uri.encode(key));LinearLayout p=new LinearLayout(this);p.setOrientation(1);Button cancel=new Button(this);cancel.setText("Cancel · Google Maps");cancel.setOnClickListener(v->finish());p.addView(cancel);map=new WebView(this);map.getSettings().setJavaScriptEnabled(true);map.getSettings().setDomStorageEnabled(true);map.getSettings().setAllowFileAccess(false);map.getSettings().setAllowContentAccess(false);map.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){Uri u=r.getUrl();if("quicknotes-map".equals(u.getScheme())&&"picked".equals(u.getHost())){try{double lat=Double.parseDouble(u.getQueryParameter("lat")),lng=Double.parseDouble(u.getQueryParameter("lng")),radius=Double.parseDouble(u.getQueryParameter("radius"));if(!Double.isFinite(lat)||!Double.isFinite(lng)||Math.abs(lat)>90||Math.abs(lng)>180)throw new Exception();setResult(RESULT_OK,new Intent().putExtra("id",getIntent().getStringExtra("id")).putExtra("lat",lat).putExtra("lng",lng).putExtra("radius",Math.max(100.584,Math.min(241401.6,radius))).putExtra("mode",getIntent().getStringExtra("mode")).putExtra("address",u.getQueryParameter("address")));finish();}catch(Exception e){}return true;}return r.isForMainFrame();}});p.addView(map,new LinearLayout.LayoutParams(-1,0,1));setContentView(p);map.loadDataWithBaseURL("https://quicknotes.local/map",html,"text/html","UTF-8",null);}catch(Exception e){new AlertDialog.Builder(this).setMessage(e.getMessage()).setPositiveButton("OK",(d,w)->finish()).setOnCancelListener(d->finish()).show();}}
 public void onDestroy(){if(map!=null)map.destroy();super.onDestroy();}
}
